h_hg = F('Fixed appliance with headgear versus aligners')
p147 = F('At the end of the protocol the headgear group had distalized')
fig2_leg = F('Fig. 2 Tooth displacement at the end of the protocol.')
p153 = F('The headgear group also had the largest side effects.')
