d.replace(p147, d.text(p147).replace('(Friedman p = 0.014; Fig. 2)', '(Friedman p = 0.014; Table 4, Fig. 5)') + ' These end-of-protocol values depend on the number of iterations, which is not calibrated to clinical time.')
f5 = d.move(fig2_img, p153)
l5 = d.move(fig2_leg, f5)
d.replace(l5, TXT_FIG2_LEG.replace('Fig. 2 Tooth displacement at the end of the protocol.', '**Fig. 5 Tooth displacement at the end of the protocol (secondary analysis).**', 1))
d.mark_par_deleted(p161)

d.replace([p for p in d.paras() if d.text(p) == 'Precision cut versus hooks'][0], 'End of the protocol: precision cut versus hooks')
p191 = F('Among the aligner designs, PC distalized')
d.replace(p191, d.text(p191).split(' At equal molar distalization the same pattern remained')[0])
